-- 063: живые реакции вместо заглушек (аудит очерёдности, раздел «в»), поздние варианты после признаний,
-- реплики «до собственных показаний». Идемпотентно: правила R417+ перезаписываются.
begin;

-- F: R417, R418, R419, R420, R421, R422, R423, R424, R425, R426, R427, R428, R429
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R417', 'R418', 'R419', 'R420', 'R421', 'R422', 'R423', 'R424', 'R425', 'R426', 'R427', 'R428', 'R429']))),'[]'::jsonb) || '[{"id": "R417", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Данияр с Игорем? — Качает головой, сочувственно. — Деньги, дорогой. Где деньги, там и ссоры.\n(пауза)\n— Я ничего не говорю. Я говорю: ты посмотри, кому база осталась.", "grants": [], "fallback": true}, {"id": "R418", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Соседка видела? — Улыбается углом рта. — Соседки всё видят, дорогой. И что надо, и что не надо.", "grants": [], "fallback": true}, {"id": "R419", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": [], "text": "Фархад читает строчку. Лицо теплеет.\n— В общежитии он был. С половины восьмого. Видишь? Мальчик у себя сидел.\n(возвращает журнал двумя руками)\n— Его не трогай, дорогой.", "grants": [], "fallback": true}, {"id": "R420", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "— Три тысячи? У Олжаса? — Пауза. Длиннее, чем нужно. — Я ему давал. За работу. Он мне с домом помогал.\n(трёт перевязанную кисть)\n— Мальчик честный. Мешки таскает.", "grants": [], "fallback": true}, {"id": "R421", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Из тех денег. Я ему отсчитал. — Голос садится. — Он не знал, за что. Мальчика не трогай.", "grants": [], "fallback": true}, {"id": "R422", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": [], "text": "Фархад смотрит на листы долго. Перекладывает один на другой.\n— Копии денег. Счетовод. Всю жизнь бумажки копирует. — Отодвигает. — Мне это зачем показываешь, дорогой?", "grants": [], "fallback": true}, {"id": "R423", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "— Телефон я не отключал. Покупатели названивают. — Разводит руками. — Доверенность у меня, всё по закону, дорогой.", "grants": [], "fallback": true}, {"id": "R424", "on": "3772cdd6-1fe9-52d0-a268-3f82441220c7", "requires": [], "text": "— Глина? Осень, дорогой. Вся Алма-Ата в глине.\n(пожимает плечами)\n— А руль чистый — значит, аккуратный был. Игорь машину любил.", "grants": [], "fallback": true}, {"id": "R425", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "— Пейджер Игоря. — Вздыхает. — В арыке? Мальчишки выкинули, может. Сейчас всё тащат.", "grants": [], "fallback": true}, {"id": "R426", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "— В четверг последний? Так он в Бишкек уехал. Валентина Петровна говорила. — Разводит руками. — Горы, дорогой. Там не ловит.", "grants": [], "fallback": true}, {"id": "R427", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "— Китайская игрушка. Игорь матери поставил, чтобы номер видела. — Смотрит на блокнот. — Почерк Валентины Петровны. Что записала, у неё спрашивай.", "grants": [], "fallback": true}, {"id": "R428", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Один ездил, да. Ерлан сказал, я знал. — Пауза. — Зачем спрашиваешь, дорогой. Всё в протоколе.", "grants": [], "fallback": true}, {"id": "R429", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Пустой был в пятницу. Игорь у меня был. В подвале. — Трёт лицо ладонью. — Машину я ночью загнал. Сам.", "grants": [], "fallback": true}]'::jsonb
where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';

-- D: R430, R431, R432, R433, R434, R435, R436, R437, R438, R439, R440, R441, R442, R443
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R430', 'R431', 'R432', 'R433', 'R434', 'R435', 'R436', 'R437', 'R438', 'R439', 'R440', 'R441', 'R442', 'R443']))),'[]'::jsonb) || '[{"id": "R430", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Данияр читает. Снимает очки, кладёт на стол дужками вверх.\n— Задушен. — Пауза. — Мне сказали: угорел. Я и это с трудом принял.", "grants": [], "fallback": true}, {"id": "R431", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"], "text": "— Задушен. — Данияр не поднимает глаз. — После того как мы заплатили. Сорок тысяч. И всё равно.", "grants": [], "fallback": true}, {"id": "R432", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "— Читал. — Поправляет очки. — «Грелся в машине». Игорь не любил этот гараж. Но я не врач. Спорить не мне.", "grants": [], "fallback": true}, {"id": "R433", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "— В морге я не был. — Выравнивает ручку параллельно калькулятору. — Не смог. Да.", "grants": [], "fallback": true}, {"id": "R434", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": [], "text": "Данияр смотрит на номера. Пальцем, по строчке.\n— Совпадают. — Кладёт лист ровно. — Я эти копии снимал не для вас. Но пусть будут для вас.", "grants": [], "fallback": true}, {"id": "R435", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": [], "text": "— У Фархада. В рисе. — Долго молчит. — Номера сверяли с моими? Значит, это наши деньги. Цифра в цифру.", "grants": [], "fallback": true}, {"id": "R436", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "— Вот откуда. — Данияр снимает очки. — Я ещё в воскресенье подумал: пять бумажек по сто у человека, который всем должен. Вот откуда.", "grants": [], "fallback": true}, {"id": "R437", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "Данияр читает дважды.\n— Фархад. В субботу. У чужого дома. — Поправляет очки. — Я сравниваю. Не обвиняю.", "grants": [], "fallback": true}, {"id": "R438", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"], "text": "— Высокий парень. — Данияр снимает очки. — На остановке пакет у меня брал высокий. В ушанке. Значит, оттуда — к Фархаду.", "grants": [], "fallback": true}, {"id": "R439", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "— Пальцы Фархада на люке. — Долго молчит. — А в воскресенье он у Валентины Петровны сидел. Руку ей гладил. Я рядом был.", "grants": [], "fallback": true}, {"id": "R440", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "— Фархада. — Данияр снимает очки. — Он вышел в девяносто пятом. Худой, в чужом пальто. Игорь ему руки не подал. Я тоже.", "grants": [], "fallback": true}, {"id": "R441", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Данияр дочитывает. Кладёт очки на стол. Ровно.\n— Значит, за долю. — Пауза. — Доли Игорь ему не дал. И я не дал. Мы оба.", "grants": [], "fallback": true}, {"id": "R442", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Алия ездила за бумагами. Она за дом на Кок-Тобе судиться собиралась. — Пожимает плечами. — Это её дело. Не моё.", "grants": [], "fallback": true}, {"id": "R443", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "— «Ф.». — Поправляет очки. — Ерлан на воротах. Мы агентству платили за ворота. Не за это.", "grants": [], "fallback": true}]'::jsonb
where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';

-- V: R444, R445, R446, R447, R448, R449, R450, R451, R452, R453
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R444', 'R445', 'R446', 'R447', 'R448', 'R449', 'R450', 'R451', 'R452', 'R453']))),'[]'::jsonb) || '[{"id": "R444", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Валентина Петровна берёт бумагу. Не читает.\n— Мне сказали: угорел, вскрывать не надо. Я подписала. — Поправляет платок. — Я тогда всё подписывала.", "grants": [], "fallback": true}, {"id": "R445", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Валентина Петровна садится. Впервые за весь разговор.\n— В подвале. Двое суток. — Пауза. — А я сидела у аппарата. На кухне. В тепле.", "grants": [], "fallback": true}, {"id": "R446", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Ерлан. С проходной. — Валентина Петровна снимает очки. — Игорь ему на Новый год конверт давал. Я сама заклеивала.", "grants": [], "fallback": true}, {"id": "R447", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "Валентина Петровна читает фамилию. Садится.\n— Фархада. — Долго молчит. — Двадцать лет за этим столом. Плов. Новый год. Дашины дни рождения.", "grants": [], "fallback": true}, {"id": "R448", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "Валентина Петровна дочитывает. Долго держит лист.\n— Мальчишка. Двадцать два года. — Пауза. — Это его голос был в трубке.\n(кладёт лист. Дальше коротко, как диктант диктует)\n— Четверг, девять вечера. Автомат. Шестьдесят тысяч, иначе внучка. С Данияром собрали сорок. Суббота, вот этот номер, Данияр отвёз деньги. — Поднимает глаза. — Я молчала ради Даши. Теперь молчать больше незачем.", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "fallback": true}, {"id": "R449", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Виктор много слышит. — Валентина Петровна поправляет скатерть. — Даник с Игорем спорили, бывает. Даник Игоря пальцем не тронул бы. Он хороший мальчик.", "grants": [], "fallback": true}, {"id": "R450", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Наши. — Голос не слушается. — Мы с Даником по всему городу собирали. По знакомым.", "grants": [], "fallback": true}, {"id": "R451", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— У Фархада. — Валентина Петровна поправляет платок. — А он у меня в воскресенье чай пил. Из Игоревой чашки.", "grants": [], "fallback": true}, {"id": "R452", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "— Двадцать восьмое? Фархад к Игорю на базу ездил? — Пауза. — Мне не говорили. Мне никто ничего не говорит.", "grants": [], "fallback": true}, {"id": "R453", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Валентина Петровна на протокол не смотрит.\n— «Грелся в машине». Это они написали, а я подписала. — Спина прямая. — Лишь бы Дашу не трогали.", "grants": [], "fallback": true}]'::jsonb
where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';

-- VK: R454, R455, R456, R457, R458, R459, R460, R461, R462, R463
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R454', 'R455', 'R456', 'R457', 'R458', 'R459', 'R460', 'R461', 'R462', 'R463']))),'[]'::jsonb) || '[{"id": "R454", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Виктор держит лист. Кепку не мнёт.\n— Задушили?.. — Пауза. — Я ж его нашёл. В воскресенье. За рулём сидел. Я думал — угорел.", "grants": [], "fallback": true}, {"id": "R455", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "— В морге? — Виктор отворачивается. — Я его в гараже видел. Мне хватит.", "grants": [], "fallback": true}, {"id": "R456", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Виктор вертит пейджер в руках.\n— Его. — Пауза. — В арыке? Мне ж сказали, в Бишкеке он. Валентина Петровна по телефону: Витя, отдыхай.", "grants": [], "fallback": true}, {"id": "R457", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "— В четверг последний? — Виктор мнёт кепку. — А мне в пятницу сказали — уехал. Выходит, он ещё в четверг…\n(не договаривает)", "grants": [], "fallback": true}, {"id": "R458", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": [], "text": "Виктор ведёт пальцем по списку.\n— «Волга» двадцать четвёртая, белая. Мамаджанов. — Пауза. — Белых «Волг» много. А фары тут не написаны.", "grants": [], "fallback": true}, {"id": "R459", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef"], "text": "— Мамаджанов. «Волга», белая. — Виктор мнёт кепку. — Та, у ворот, тоже белая была. Без левой фары. Фару проверьте.", "grants": [], "fallback": true}, {"id": "R460", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "— Двадцать восьмое… — Виктор кивает. — Игорь после этого весь вечер молчал. Я его домой вёз — ни слова.", "grants": [], "fallback": true}, {"id": "R461", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Виктор снимает кепку. Совсем.\n— Фархад. — Долго молчит. — Он же с Игорем с самого начала. Я думал, помирились.", "grants": [], "fallback": true}, {"id": "R462", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "— Ерлан? С проходной? — Виктор мнёт кепку. — Я с ним каждое утро чай пил. Про четверги он знал, конечно. На базе каждый знал.", "grants": [], "fallback": true}, {"id": "R463", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "Виктор дочитывает. Кепку мнёт.\n— Одна фара… — Пауза. — Это у Шмидтов? Я там не бываю. Я при Игоре был. А по четвергам он без меня.", "grants": [], "fallback": true}]'::jsonb
where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';

-- A: R464, R465, R466, R467, R468, R469, R470, R471
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R464', 'R465', 'R466', 'R467', 'R468', 'R469', 'R470', 'R471']))),'[]'::jsonb) || '[{"id": "R464", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Алия читает быстро. Сначала выводы.\n— «Грелся в машине». Я ему десять лет говорила: угоришь в этом гараже. — Возвращает лист. — Только вскрытия не было. Без вскрытия это не диагноз.", "grants": [], "fallback": true}, {"id": "R465", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "— Экспертиза не назначена. — Алия коротко усмехается. — Конечно. Направление пусть следователь пишет, а не родственники.", "grants": [], "fallback": true}, {"id": "R466", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Данияр ругался с Игорем? — Алия пожимает плечами. — Данияр считает. Он и ругается, как считает. Тихо и в столбик.", "grants": [], "fallback": true}, {"id": "R467", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Данияр отвёз выкуп. И копии снял. — Пауза. — Мне ни слова. Матери Даши — ни слова.", "grants": [], "fallback": true}, {"id": "R468", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "Алия дочитывает. Губы сжаты.\n— Мальчишка с базара. Свекрови названивал. Грозил моей дочери. — Пауза. — Ради чужих денег.", "grants": [], "fallback": true}, {"id": "R469", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "— Фархад. — Алия долго молчит. — Он Дашу на руках носил.", "grants": [], "fallback": true}, {"id": "R470", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— «Я тебя узнал». — Алия закрывает глаза. — Игорь всех узнавал. По шагам, по кашлю. Вот и узнал.", "grants": [], "fallback": true}, {"id": "R471", "on": "7a9bdd9a-4323-5342-a3bd-24301a6d6e88", "requires": [], "text": "Алия смотрит на таблицу. Слишком быстро.\n— Тридцать седьмой — мало ли чей. — Возвращает лист. — Мужские ищите. Я в своей обуви хожу, где хочу.", "grants": [], "fallback": true}]'::jsonb
where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';

-- ER: R472, R473, R474, R475, R476, R477
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R472', 'R473', 'R474', 'R475', 'R476', 'R477']))),'[]'::jsonb) || '[{"id": "R472", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Сигарета у Ерлана замирает на полпути.\n— Задушили?.. — Пауза. — Мне сказали: угорел, и всё. Я на воротах, братан. Мне что скажут.", "grants": [], "fallback": true}, {"id": "R473", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "— Мой почерк. — Ерлан затягивается. — Двадцать восьмое, Мамаджанов, полчаса. Пришёл, ушёл. Я пишу, братан. Я не слушаю.", "grants": [], "fallback": true}, {"id": "R474", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": [], "text": "— «Волга» белая? — Ерлан стряхивает пепел мимо пепельницы. — У ворот всякие машины бывают, братан. Я номера пишу, когда въезжают.", "grants": [], "fallback": true}, {"id": "R475", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "— Горный Гигант? Я там не был. — Ерлан качает ногой. — У меня смена. Журнал есть, смотри.", "grants": [], "fallback": true}, {"id": "R476", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "— Фархада берёте? — Ерлан долго молчит. Тушит сигарету. — Ну. Берите.", "grants": [], "fallback": true}, {"id": "R477", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "— Пальцы, значит. — Ерлан затягивается. — Я с ним за руку здоровался, братан. И всё. Моих там нет.", "grants": [], "fallback": true}]'::jsonb
where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';

-- T: R478, R479, R480, R481, R482, R483, R484, R485
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R478', 'R479', 'R480', 'R481', 'R482', 'R483', 'R484', 'R485']))),'[]'::jsonb) || '[{"id": "R478", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "Тамара Фёдоровна держит справку на вытянутой руке.\n— Племянник Фархада? Не знаю такого, деточка. Молодёжь сейчас вся одинаковая.", "grants": [], "fallback": true}, {"id": "R479", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Племянник? Высокий, молодой? — Тамара Фёдоровна прижимает руку к груди. — Господи. Так это он с ним из «Волги» выходил. И печку он топил.", "grants": [], "fallback": true}, {"id": "R480", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Ушанка… Такая и была, деточка. И куртка тёмная. — Пауза. — Только лица я не видела. Темно, света ни у кого.", "grants": [], "fallback": true}, {"id": "R481", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— Мальчик… — Тамара Фёдоровна качает головой. — А я думала, помощник. Дом показывать.", "grants": [], "fallback": true}, {"id": "R482", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Тамара Фёдоровна долго молчит.\n— Фархад. А такой вежливый. Мне в сентябре дрова до сарая донёс. — Шёпотом: — Gott…", "grants": [], "fallback": true}, {"id": "R483", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "— Арестовали? — Тамара Фёдоровна крестится. — Господи. А дом Шмидтов теперь кто продавать будет?", "grants": [], "fallback": true}, {"id": "R484", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Лампа? Видела, деточка. На всей улице темно, а у Шмидтов в окне свет. Я ещё подумала: керосинка.", "grants": [], "fallback": true}, {"id": "R485", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "— Покупателей Фархад водил, да. Днём. — Тамара Фёдоровна смотрит поверх забора. — А вы про какой день спрашиваете, деточка?", "grants": [], "fallback": true}]'::jsonb
where id = '631694f6-0ec1-523d-9f2a-599f875223c1';

-- O: R486, R487, R488, R489, R490, R491, R492, R493, R494, R495, R496, R497, R498, R499, R500, R501
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R486', 'R487', 'R488', 'R489', 'R490', 'R491', 'R492', 'R493', 'R494', 'R495', 'R496', 'R497', 'R498', 'R499', 'R500', 'R501']))),'[]'::jsonb) || '[{"id": "R486", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "Олжас смотрит на снимки. Сразу в пол.\n— Подвал. Я не знаю. Я на базаре работаю.", "grants": [], "fallback": true}, {"id": "R487", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Там. — Олжас не поднимает глаз. — Я ему лампу оставлял. Чтоб не в темноте.", "grants": [], "fallback": true}, {"id": "R488", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "— Телефон. У всех телефон. — Олжас трёт ладони о колени.", "grants": [], "fallback": true}, {"id": "R489", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Оттуда. В субботу. — Смотрит в пол. — Аке номер на бумажке написал.", "grants": [], "fallback": true}, {"id": "R490", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Рис. У аке всегда рис. Он плов делает. — Олжас смотрит в сторону.", "grants": [], "fallback": true}, {"id": "R491", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Это из пакета. — Олжас говорит в пол. — Я ему отдал. Дальше его.", "grants": [], "fallback": true}, {"id": "R492", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Это аке ботинки. — Олжас поднимает ногу. — У меня сорок пятый.", "grants": [], "fallback": true}, {"id": "R493", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": [], "text": "— Бумажки какие-то. — Олжас мотает головой. — Я не понимаю.", "grants": [], "fallback": true}, {"id": "R494", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Номера переписали?.. — Олжас закрывает лицо руками. — Значит, всё равно бы нашли.", "grants": [], "fallback": true}, {"id": "R495", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "— Аке забирают? — Олжас встаёт и снова садится. — Он мне работу нашёл. Комнату.", "grants": [], "fallback": true}, {"id": "R496", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "— Ногтями? — Олжас смотрит на свои руки. Поворачивает ладонями вверх. — Не я. Смотрите. У меня нет.", "grants": [], "fallback": true}, {"id": "R497", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "— Конверт? На похороны? — Олжас молчит. — Аке такой. Всем помогает.", "grants": [], "fallback": true}, {"id": "R498", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Из тех… — Олжас поднимает голову. — Он ей отнёс? Матери?", "grants": [], "fallback": true}, {"id": "R499", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Олжас читает. Поднимает глаза.\n— Задушен?.. Аке сказал: отпустим. Утром, за городом. Он сказал.\n(пауза)\n— Я в общаге был.", "grants": [], "fallback": true}, {"id": "R500", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Немцев дом. — Олжас смотрит в пол. — Там мы его и держали.", "grants": [], "fallback": true}, {"id": "R501", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Рука у аке? — Олжас трёт ладони о колени. — Не знаю. В субботу целая была. Когда я уходил.", "grants": [], "supersedes": ["R90"]}]'::jsonb
where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';

-- Z: R502, R503, R504, R505
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R502', 'R503', 'R504', 'R505']))),'[]'::jsonb) || '[{"id": "R502", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "— Фархад принёс. В воскресенье. Я видела, как он ей конверт в руку вложил. — Поджимает губы. — Вот кто человек, подумала. Я не сплетничаю. Я констатирую.", "grants": [], "fallback": true}, {"id": "R503", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Зоя Михайловна снимает полотенце с плеча.\n— Фархад? Я про него говорила: вот кто человек. — Пауза. — Беру свои слова обратно. Констатирую.", "grants": [], "fallback": true}, {"id": "R504", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "— Того, с конвертом? — Зоя Михайловна долго молчит. — Ну. Я ничего не говорю.", "grants": [], "fallback": true}, {"id": "R505", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Зоя Михайловна садится на табурет.\n— Задушили? Игоря? — Пауза. — Валентина Петровна сказала: угорел. Я не сплетничаю. Но я её третий день за стенкой не слышу.", "grants": [], "fallback": true}]'::jsonb
where id = '753087d6-7c38-5bf7-889e-3c4477902369';

-- R: R506, R507
update characters set reaction_rules = coalesce((select jsonb_agg(r order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o) where not (r->>'id' = any(array['R506', 'R507']))),'[]'::jsonb) || '[{"id": "R506", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "— Из его комнаты? Куртка его, ушанка его. — Роза-апа поджимает губы. — А деньги не знаю. Я по карманам не лазаю.", "grants": [], "fallback": true}, {"id": "R507", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— Олжас? — Роза-апа качает головой. — Тихий же. Полы за собой моет. Ой-бай.", "grants": [], "fallback": true}]'::jsonb
where id = 'ad04679a-62fd-52ac-a043-6e04873ad6b3';

-- Олжас, «Фархад: перевязанная кисть»: на очной ставке (R197) поздний вариант R501 не показывать.
update characters set reaction_rules = (select jsonb_agg(case when r->>'id'='R197' then jsonb_set(r,'{supersedes}','["R90","R501"]'::jsonb) else r end order by o) from jsonb_array_elements(reaction_rules) with ordinality t(r,o))
where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';

commit;
